  "anomalies": [
    {
      "category": "footprint_mismatch",
      "components": ["C13"],
      "pins": ["C13.1", "C13.2"],
      "nets": ["unconnected-(C13-Pad1)", "GND"],
      "observed": "C13 is a 0.1 uF capacitor (Device:C) but is assigned an inductor footprint, and pin 1 is left on an unconnected net while pin 2 is tied to GND.",
      "expected": "A capacitor should use a capacitor footprint and, if populated, have both terminals connected to its intended node; an unused part should be omitted or marked no-connect. The specified FAN53610 decoupling network uses connected input/output capacitors, not a floating capacitor in an inductor footprint.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(comp (ref \"C13\") (value \"0.1uF\") (footprint \"Inductor_SMD:L_0805_2012Metric_Pad1.05x1.20mm_HandSolder\")"
        },
        {
          "source": "netlist",
          "quote": "(net (code \"59\") (name \"unconnected-(C13-Pad1)\") (class \"Default\") (node (ref \"C13\") (pin \"1\") (pintype \"passive\")))"
        },
        {
          "source": "spice",
          "quote": "C13 unconnected-_C13-Pad1_ 0 0.1u"
        }
      ],
      "impact": "If C13 was intended as bypass/decoupling, the floating pin prevents it from functioning; the inductor footprint may also cause assembly or sourcing of the wrong 0805 part type.",
      "confidence": 0.65
    }
  ],
  "summary": "Most connectivity matches the specification, but C13 is a 0.1 uF capacitor placed in an inductor footprint with one terminal unconnected, which is a supported deviation from the intended power-supply decoupling design."
}

